// tools/copy.mjs — the words a buyer reads: the brochure, the white paper and the questions. Written from the records
// and verdicts (tools/words.mjs passes them in), so what the page claims is what the sealed rules found, whichever way
// they fell. Nothing here is a hand-typed result. Supplier facts are the estate's: AI Native Solutions, support agreed
// per deployment, MIT with no licence fee, no prices on a product page.

import { readFileSync, existsSync } from 'node:fs';
import { organRows } from './rows.mjs';

const f3 = (x) => (typeof x === 'number' && Number.isFinite(x) ? x.toFixed(3) : '…');
const gb = (x) => (typeof x === 'number' ? x.toLocaleString('en-GB') : '…');
const NAME = { telco: 'telecom customers', shop: 'shop sessions' };
const sg = (x) => (x >= 0 ? '+' : '−') + Math.abs(x).toFixed(3);
const sides = (g) => ['telco', 'shop'].map((d) => (g[d].vsMonolith.lead >= 0 ? 'level with it on the ' + NAME[d] + ' (' + sg(g[d].vsMonolith.lead) + ')' : sg(g[d].vsMonolith.lead).slice(1) + ' behind it on the ' + NAME[d])).join(', and ');
const FRESH = { bank: 'bank calls', adult: 'census people' };
/** whether any organ has won the gate: then an earlier organ's “not won” is history, said in the past */
const gateWon = (R, pass) => ['2f', '2g', '2h', '2i', '2j', '2k'].some((k) => R[k] && pass(R, k, 'GATE'));
/** whether organ 2j's pass was repeated, unchanged, in organ 2k */
const repeated = (R, pass) => !!R['2j'] && !!R['2k'] && pass(R, '2j', 'GATE') && pass(R, '2k', 'GATE');
/** organ 2f in one paragraph, from its record and verdict: each of the gate’s three tests, held or failed, with its numbers */
export function retake(R, pass) {
  const r = R['2f'].r, t = (id, what, get) => what + ' ' + (pass(R, '2f', id) ? 'held' : 'failed') + ' (' + ['bank', 'adult'].map((d) => get(r[d])).join('; ') + ').';
  return 'On two datasets no attempt had touched, ' + r.bank.cases.toLocaleString('en-GB') + ' bank calls and ' + r.adult.cases.toLocaleString('en-GB') + ' census people held out (organ 2f), the mesh scored ' + f3(r.bank.composedAuc) + ' and ' + f3(r.adult.composedAuc) + '. '
    + t('N2', 'Beating its best department', (x) => f3(x.vsBest.a) + ' against ' + f3(x.vsBest.b) + ', bound ' + sg(x.vsBest.low95)) + ' '
    + t('N3', 'Approaching the frontier model on 300 cases each', (x) => f3(x.frontier.vs.a) + ' against ' + f3(x.frontier.vs.b) + ', bound ' + sg(x.frontier.vs.low95)) + ' '
    + t('N4', 'Growing as departments join', (x) => x.growth.map((g) => f3(g.testAuc)).join(' → ')) + ' '
    + (pass(R, '2f', 'GATE') ? 'All three held together, on fresh cases: the gate is won.' : gateWon(R, pass) ? 'So the gate was not won there; every failed test is kept.' : 'So the gate is not won, and by the spec nothing scales; every failed test is kept.');
}
const FRESH2 = { hospital: 'hospital stays', credit: 'credit clients' };
/** organ 2g in one paragraph, from its record and verdict */
export function retake2(R, pass) {
  const r = R['2g'].r, live = (d) => r[d].live.length > 0, t = (id, what, held, get) => what + ': ' + ['hospital', 'credit'].map((d) => (held(r[d]) ? 'held' : 'failed') + ' on the ' + FRESH2[d] + (live(d) ? ' (' + get(r[d]) + ')' : ' (no mesh)')).join(', ') + '.';
  const none = ['hospital', 'credit'].filter((d) => !r[d].live.length).map((d) => ' On the ' + FRESH2[d] + ' every department was cut at its bar on its own (the best ' + f3(Math.max(...r[d].departments.map((x) => x.gateAuc))) + ' against 0.6), so no mesh formed, while every record pooled scored ' + f3(r[d].monolith.boosted.b) + ': a bar that judges each department alone cut a signal spread thin across them.').join('');
  return 'On two more datasets no attempt had touched, ' + r.hospital.cases.toLocaleString('en-GB') + ' hospital stays and ' + r.credit.cases.toLocaleString('en-GB') + ' credit clients held out (organ 2g, with 2f’s measurement faults fixed), the mesh scored ' + f3(r.hospital.composedAuc) + ' and ' + f3(r.credit.composedAuc) + '.' + none + ' '
    + t('P2', 'Beating its best department', (x) => x.live.length >= 2 && x.vsBest.low95 > 0, (x) => f3(x.vsBest.a) + ' against ' + f3(x.vsBest.b) + ', bound ' + sg(x.vsBest.low95)) + ' '
    + t('P3', 'Approaching the frontier model on 1,200 cases', (x) => x.frontier.vs.low95 > -0.02, (x) => f3(x.frontier.vs.a) + ' against ' + f3(x.frontier.vs.b) + ', bound ' + sg(x.frontier.vs.low95)) + ' '
    + t('P4', 'Growing measurably as departments join', (x) => x.live.length >= 2 && x.growth.every((g, k) => k === 0 || g.testAuc >= x.growth[k - 1].testAuc) && x.fullVsFirst.low95 > 0, (x) => x.growth.map((g) => f3(g.testAuc)).join(' → ') + ', bound ' + sg(x.fullVsFirst.low95)) + ' '
    + (pass(R, '2g', 'GATE') ? 'All three held together, on fresh cases: the gate is won.' : gateWon(R, pass) ? 'So the gate was not won there; every failed test is kept.' : 'So the gate is not won, and by the spec nothing scales; every failed test is kept.');
}
const FRESH3 = { coupon: 'coupon offers', cover: 'forest cells' };
