  const r = R['2h'].r, live = (d) => r[d].live.length > 0, t = (what, held, get) => what + ': ' + ['coupon', 'cover'].map((d) => (held(r[d]) ? 'held' : 'failed') + ' on the ' + FRESH3[d] + (live(d) ? ' (' + get(r[d]) + ')' : ' (no mesh)')).join(', ') + '.';
