    + t('Approaching the frontier model on 1,200 cases', (x) => x.frontier.vs.low95 > -0.02, (x) => f3(x.frontier.vs.a) + ' against ' + f3(x.frontier.vs.b) + ', bound ' + sg(x.frontier.vs.low95)) + ' '
    + t('Growing measurably as departments join', (x) => x.live.length >= 2 && x.growth.every((g, k) => k === 0 || g.testAuc >= x.growth[k - 1].testAuc) && x.fullVsFirst.low95 > 0, (x) => x.growth.map((g) => f3(g.testAuc)).join(' → ') + ', bound ' + sg(x.fullVsFirst.low95)) + ' '
    + (pass(R, '2h', 'GATE') ? 'All three held together in both, on fresh cases: the gate is won.' : gateWon(R, pass) ? 'So the gate was not won there; every failed test is kept.' : 'So the gate is not won, and by the spec nothing scales; every failed test is kept.');
