/** the freshest fresh-data results, domain by domain: the mesh against every record pooled (or no mesh where none formed) */
function freshest(R) {
  const names = { bank: 'bank calls', adult: 'census people', hospital: 'hospital stays', credit: 'credit clients', coupon: 'coupon offers', cover: 'forest cells', hotel: 'hotel bookings', news: 'news articles' };
  const rows = ['2f', '2g', '2h', '2i'].filter((k) => R[k]).flatMap((k) => Object.keys(names).filter((d) => R[k].r[d]).map((d) => ({ k, d, x: R[k].r[d] })));
  if (!rows.length) return '';
  return 'On data no attempt had touched before it, the mesh against every record pooled in one place: ' + rows.map(({ k, d, x }) => names[d] + ' (organ ' + k + ') ' + ((x.live || []).length ? f3(x.composedAuc) + ' against ' + f3(x.monolith.boosted.b) : 'no mesh formed, pooled ' + f3(x.monolith.boosted.b))).join('; ') + '.';
}
/** what one score per department carries, from the checks made on FIT and GATE alone (data/diagnose-2, -3, -4): for each
 *  dataset, every record pooled against the better coupling of one boosted model per department, one score each */
const CHECKED = { telco: 'telecom customers', shop: 'shop sessions', bank: 'bank calls', adult: 'census people', hospital: 'hospital stays', credit: 'credit clients', coupon: 'coupon offers', cover: 'forest cells', hotel: 'hotel bookings', news: 'news articles' };
export function oneScore(base = new URL('../data/', import.meta.url)) {
  const at = (f) => (existsSync(new URL(f, base)) ? JSON.parse(readFileSync(new URL(f, base), 'utf8')) : {});
  const files = [at('diagnose-2.json'), at('diagnose-3.json'), at('diagnose-4.json')];
  return Object.keys(CHECKED).flatMap((d) => files.filter((r) => r[d]).slice(-1).map((r) => { const m = r[d].meshBoosted || r[d].boostedMesh; return { d, pooled: r[d].pooled, mesh: Math.max(m.linear, m.trees), gap: r[d].pooled - Math.max(m.linear, m.trees) }; }));
}
function oneScoreText() {
  const rows = oneScore(), near = rows.filter((x) => x.gap <= 0.01).length, close = rows.filter((x) => x.gap <= 0.02), far = rows.filter((x) => x.gap > 0.02);
  if (!rows.length) return '';
  return 'In the checks made on held-back cases alone (FIT and GATE), one boosted model per department, each sending one score, came within a hundredth of every record pooled on ' + near + ' of the ' + rows.length + ' datasets and within two hundredths on ' + (close.length === rows.length ? 'all ' + rows.length : close.length)
    + (far.length ? '; it trailed ' + far.map((x) => 'on the ' + CHECKED[x.d] + ' by ' + f3(x.gap) + ' (' + f3(x.mesh) + ' against ' + f3(x.pooled) + ')').join(' and ') : '') + '.';
}
const OUTCOME = { bank: 'calls that sold a deposit', adult: 'people earning over $50,000', hospital: 'hospital stays followed by a readmission within 30 days', credit: 'card holders who defaulted the next month', coupon: 'coupons accepted', cover: 'forest cells under spruce or fir', hotel: 'hotel bookings cancelled', news: 'news articles shared 1,400 times or more' };
/** how rare the outcome was, across the fresh test sets: the rarest and the commonest, from the records */
function rates(R) {
  const all = ['2f', '2g', '2h', '2i'].filter((k) => R[k]).flatMap((k) => Object.keys(CHECKED).filter((d) => R[k].r[d] && R[k].r[d].cases).map((d) => ({ d, rate: R[k].r[d].outcomes / R[k].r[d].cases })));
  if (!all.length) return null;
  const lo = all.reduce((a, x) => (x.rate < a.rate ? x : a)), hi = all.reduce((a, x) => (x.rate > a.rate ? x : a));
  return { lo, hi, pct: (x) => (100 * x.rate).toFixed(1) + '%' };
}
/** Gary W. Floyd's papers this build draws on (read off the papers; the build is the estate's): each with what it draws */
export const GARY = [
  ["“NEXUS — Distributed Synthetic Intelligence: Architecture, Ethics, and the GEP-Native Mind,” 2026", 'intelligence distributed across specialist organs: departments grow their own specialists and compose, records never shared.'],
  ["“From GEP Stabilization to Dual-Map Ethical Reasoning: A derivation of positive ethical evidence, negative ethical evidence, and non-legal moral reasoning,” Derivation v0.2", 'a stable system can stabilize a wrong reference, so every claim here is sealed and judged on cases nothing touched, and a failed prediction is kept.'],
  ["“The Laws of Entropy-Time: Rewriting Thermodynamics with the Guided Entropy Principle,” February 2026", 'claims split into properties and predictions, each with the test that could fail it.'],
];
/** every fresh dataset, once, as its sources record cites it (data/fresh*-sources.json) */
export function datasets(base = new URL('../data/', import.meta.url)) {
  const seen = new Set();
  return ['fresh-sources.json', 'fresh2-sources.json', 'fresh3-sources.json', 'fresh4-sources.json'].filter((f) => existsSync(new URL(f, base)))
    .flatMap((f) => JSON.parse(readFileSync(new URL(f, base), 'utf8')).files).filter((x) => x.cite && x.cite !== 'as above' && x.dataset && !seen.has(x.dataset.split(',')[0]) && seen.add(x.dataset.split(',')[0]));
}
