/** whether any department of organ 2i fielded boosted trees (alone or in the relay): then a node is not only rules */
const fieldedTrees = (R) => (!!R['2i'] && ['hotel', 'news'].some((d) => R['2i'].r[d].departments.some((x) => x.fielded === 'boosted') || R['2i'].r[d].relay.some((x) => x.fielded === 'boosted'))) || (!!R['2j'] && R['2j'].r.health.steps.some((x) => x.fielded === 'boosted')) || (!!R['2k'] && R['2k'].r.dropout.steps.some((x) => x.fielded === 'boosted'));
const tally = (R) => { const v = Object.values(R).flatMap((x) => x.v); return v.filter((x) => x.pass).length + ' of ' + v.length + ' sealed rules held across ' + Object.keys(R).length + ' judged organs'; };

/** the questions, as data: the visible FAQ and the structured data are both made from this one list */
